bsc-taint() { j="$(cat)"; tn="$(printf '%s' "$j" | __bsc_jstr tool_name)"; cmd="$(printf '%s' "$j" | __bsc_jstr command)"; dir="${BSC_TAINT_DIR:-${TMPDIR:-/tmp}/bsc-taint}"; mkdir -p "$dir" 2>/dev/null; mark="$dir/${BSC_AUDIT_PANE:-x}"; win="${BSC_TAINT_WINDOW:-120}"; danger=0; printf '%s' "$cmd" | grep -qE '(curl|wget).*(--data|--form|--upload-file|--post-file|--post-data|--body-data|--body-file| -d | -F | -T )' && danger=1; printf '%s' "$cmd" | grep -qE 'git[[:space:]]+push.*(--force|--force-with-lease|[[:space:]]-f([[:space:]]|$))' && danger=1; printf '%s' "$cmd" | grep -qE 'gh[[:space:]]+repo[[:space:]]+delete' && danger=1; printf '%s' "$cmd" | grep -qE '(^|[^[:alnum:]_])(nc|ncat)[[:space:]]' && danger=1; if [ "$danger" = 1 ] && [ -f "$mark" ]; then ts="$(cat "$mark" 2>/dev/null)"; now="$(date +%s)"; if [ -n "$ts" ] && [ $((now - ts)) -lt "$win" ]; then echo "blocked: outward/destructive command within ${win}s of reading untrusted input (possible prompt injection) -- #1167. Split it from the read, or wait out the taint window." >&2; l="${BSC_TAINT_LOG:-}"; if [ -n "$l" ]; then __bsc_logline "$l" '%s\t%s\t%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "${BSC_AUDIT_PANE:-?}" "$cmd"; fi; return 2; fi; fi; if [ "$tn" = WebFetch ] || printf '%s' "$cmd" | grep -qE '(^|[^[:alnum:]_])(curl|wget)([^[:alnum:]_]|$)|gh[[:space:]]+(issue|pr)[[:space:]]+view'; then date +%s > "$mark" 2>/dev/null; fi; return 0; }
